  const [collaborationLoading,setCollaborationLoading] = useState(false);
  const [richComments,setRichComments] = useState<RichComment[]>([]);
  const [commentsLoading,setCommentsLoading] = useState(false);
  const [notifications,setNotifications] = useState<AppNotification[]>([]);
  const [notificationsLoading,setNotificationsLoading] = useState(false);
  const [showNotifications,setShowNotifications] = useState(false);
  const [serverVersion,setServerVersion] = useState(0);
  const [livePresence,setLivePresence] = useState<LivePresence[]>([]);
  const [syncConflict,setSyncConflict] = useState<{remoteVersion:number}|null>(null);
  const [syncBusy,setSyncBusy] = useState(false);
  const [spacePressed,setSpacePressed] = useState(false);
  const canvasRef = useRef<HTMLDivElement|null>(null);
  const spacePressedRef = useRef(false);
  const suppressCardClickRef = useRef(false);
  const dragRef = useRef<{id?:string;startX:number;startY:number;nodeX?:number;nodeY?:number;panX?:number;panY?:number;mode:"node"|"pan";moved?:boolean}|null>(null);
  const dragFrameRef = useRef<number|null>(null);
  const pendingPointerRef = useRef<{clientX:number;clientY:number}|null>(null);

  useEffect(()=>{ fetch("/api/workspace").then(r=>r.json()).then(data=>{ if(data.workspace){setWorkspace(data.workspace);if(data.workspace.trial_ends_at)setDaysLeft(Math.max(0,Math.ceil((new Date(data.workspace.trial_ends_at).getTime()-new Date().getTime())/86400000)))}if(data.access)setAccess(data.access);if(data.entitlement)setEntitlement(data.entitlement);if(Number.isFinite(data.version))setServerVersion(data.version||0); if(data.state){const normalized=normalizeLoadedState(data.state);const params=new URLSearchParams(window.location.search);const sharedMapId=params.get("map");const reviewMapId=params.get("review");const targetMapId=reviewMapId||sharedMapId;if(targetMapId&&normalized.maps.some(map=>map.id===targetMapId&&!map.archived)){normalized.activeMapId=targetMapId;normalized.view="map";setMapFullscreen(true);if(reviewMapId)setShowClientPortal(true)}setState(normalized);if((data.state.schemaVersion??0)<2&&data.access?.canEdit!==false)setDirty(true)} setReady(true);setSaveStatus("Salvo");if(localStorage.getItem("mo-onboarding-completed")!=="true")setShowOnboarding(true);setSidebarCollapsed(localStorage.getItem("mo-sidebar-collapsed")==="true"); }).catch(()=>{setReady(true);setSaveStatus("Modo offline");}); },[]);
  const refreshWorkspaceState=useCallback(async(label="Sincronizado com a equipe")=>{const response=await fetch("/api/workspace");const data=await response.json();if(!response.ok)throw new Error(data.error||"Não foi possível atualizar o mapa");if(data.workspace)setWorkspace(data.workspace);if(data.access)setAccess(data.access);if(data.entitlement)setEntitlement(data.entitlement);if(data.state){const incoming=normalizeLoadedState(data.state);setState(current=>{const activeMapId=incoming.maps.some(map=>map.id===current.activeMapId)?current.activeMapId:incoming.activeMapId;return {...incoming,activeMapId,view:current.view}});setSelectedId(current=>current&&incoming.nodes.some(node=>node.id===current)?current:null);setHistory([]);setFuture([])}setServerVersion(Number(data.version)||0);setDirty(false);setSyncConflict(null);setSaveStatus(label)},[]);
  useEffect(()=>{ if(!ready||!dirty||!access.canEdit||syncConflict)return; const timer=setTimeout(()=>{ setSaveStatus("Salvando..."); fetch("/api/workspace",{method:"POST",headers:{"content-type":"application/json","x-workspace-version":String(serverVersion)},body:JSON.stringify(state)}).then(async r=>{const data=await r.json();if(r.status===409&&data.conflict){setSyncConflict({remoteVersion:Number(data.currentVersion)||serverVersion});setSaveStatus("Conflito protegido");setToast("Outra pessoa salvou antes. Suas alterações foram preservadas.");return null}if(!r.ok)throw new Error(data.error||"Não foi possível salvar");return data}).then(data=>{if(!data)return;setServerVersion(Number(data.version)||serverVersion);setSaveStatus("Salvo");setDirty(false)}).catch(error=>{setSaveStatus("Erro ao salvar");setToast(error instanceof Error?error.message:"Erro ao salvar")}); },700); return()=>clearTimeout(timer); },[state,ready,dirty,access.canEdit,serverVersion,syncConflict]);
  useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(""),2500);return()=>clearTimeout(t)},[toast]);
  useEffect(()=>{if(!ready||state.view!=="map"||showOnboarding||showMapTour||localStorage.getItem("mo-map-tour-completed")==="true")return;const timer=window.setTimeout(()=>{setMapTourStep(0);setShowMapTour(true)},0);return()=>window.clearTimeout(timer)},[ready,state.view,showOnboarding,showMapTour]);
  useEffect(()=>{if(!selectedId)return;let active=true;const timer=window.setTimeout(()=>{setFilesLoading(true);fetch(`/api/files?nodeId=${encodeURIComponent(selectedId)}`).then(async response=>{const data=await response.json();if(!response.ok)throw new Error(data.error||"Não foi possível carregar os arquivos");if(active)setNodeFiles(data.files||[])}).catch(error=>{if(active){setNodeFiles([]);setToast(error instanceof Error?error.message:"Erro ao carregar arquivos")}}).finally(()=>{if(active)setFilesLoading(false)})},0);return()=>{active=false;window.clearTimeout(timer)}},[selectedId]);
  useEffect(()=>{if(!ready)return;let active=true;const timer=window.setTimeout(()=>{setApprovalsLoading(true);fetch("/api/approvals").then(async response=>{const data=await response.json();if(!response.ok)throw new Error(data.error||"Não foi possível carregar as aprovações");if(active)setApprovals(data.approvals||[])}).catch(error=>{if(active)setToast(error instanceof Error?error.message:"Erro ao carregar aprovações")}).finally(()=>{if(active)setApprovalsLoading(false)})},0);return()=>{active=false;window.clearTimeout(timer)}},[ready]);
  const loadCollaboration=useCallback(async()=>{setCollaborationLoading(true);try{const response=await fetch("/api/collaboration");const data=await response.json();if(!response.ok)throw new Error(data.error||"Não foi possível carregar a equipe");setCollaboration(data)}catch(error){setToast(error instanceof Error?error.message:"Erro ao carregar equipe")}finally{setCollaborationLoading(false)}},[]);
  const loadNotifications=useCallback(async()=>{setNotificationsLoading(true);try{const response=await fetch("/api/notifications");const data=await response.json();if(!response.ok)throw new Error(data.error||"Não foi possível carregar as notificações");setNotifications(data.notifications||[])}catch(error){setToast(error instanceof Error?error.message:"Erro ao carregar notificações")}finally{setNotificationsLoading(false)}},[]);
  useEffect(()=>{if(!ready)return;const timer=window.setTimeout(()=>{void loadCollaboration();void loadNotifications()},0);return()=>window.clearTimeout(timer)},[ready,loadCollaboration,loadNotifications]);
  const selectedCommentMapId=selectedId?state.nodes.find(item=>item.id===selectedId)?.mapId||"":"";
  useEffect(()=>{let active=true;const timer=window.setTimeout(()=>{if(!selectedId||!selectedCommentMapId){setRichComments([]);return}setCommentsLoading(true);fetch(`/api/comments?nodeId=${encodeURIComponent(selectedId)}&mapId=${encodeURIComponent(selectedCommentMapId)}`).then(async response=>{const data=await response.json();if(!response.ok)throw new Error(data.error||"Não foi possível carregar os comentários");if(active)setRichComments(data.comments||[])}).catch(error=>{if(active){setRichComments([]);setToast(error instanceof Error?error.message:"Erro ao carregar comentários")}}).finally(()=>{if(active)setCommentsLoading(false)})},0);return()=>{active=false;window.clearTimeout(timer)}},[selectedId,selectedCommentMapId]);
  const loadRemoteVersion=async()=>{setSyncBusy(true);try{await refreshWorkspaceState("Versão da equipe carregada");setToast("Mapa atualizado com a versão mais recente da equipe")}catch(error){setToast(error instanceof Error?error.message:"Erro ao carregar a versão da equipe")}finally{setSyncBusy(false)}};
  const keepLocalVersion=async()=>{if(!syncConflict)return;setSyncBusy(true);try{const response=await fetch("/api/workspace",{method:"POST",headers:{"content-type":"application/json","x-workspace-version":String(syncConflict.remoteVersion),"x-workspace-conflict-resolution":"overwrite"},body:JSON.stringify(state)});const data=await response.json();if(response.status===409&&data.conflict){setSyncConflict({remoteVersion:Number(data.currentVersion)||syncConflict.remoteVersion});throw new Error("A equipe salvou novamente. Revise e confirme mais uma vez.")}if(!response.ok)throw new Error(data.error||"Não foi possível manter suas alterações");setServerVersion(Number(data.version)||syncConflict.remoteVersion);setDirty(false);setSyncConflict(null);setSaveStatus("Salvo");setToast("Suas alterações foram mantidas e sincronizadas") }catch(error){setToast(error instanceof Error?error.message:"Erro ao resolver conflito")}finally{setSyncBusy(false)}};
  useEffect(()=>{if(!ready)return;let active=true;let running=false;let interval:number|undefined;const heartbeat=async()=>{if(running||document.visibilityState==="hidden")return;running=true;try{const mapId=state.view==="map"?state.activeMapId:"";const response=await fetch("/api/realtime",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({mapId,nodeId:mapId?selectedId||"":"",clientVersion:serverVersion})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Sincronização indisponível");if(!active)return;setLivePresence(data.presence||[]);const remoteVersion=Number(data.version)||0;const decision=remoteSyncDecision(serverVersion,remoteVersion,dirty,Boolean(syncConflict));if(decision==="refresh")await refreshWorkspaceState("Atualizado com a equipe");else if(decision==="defer"&&!syncConflict)setSaveStatus("Mudanças da equipe aguardando")}catch{if(active&&state.view!=="map")setLivePresence([])}finally{running=false}};const starter=window.setTimeout(()=>{void heartbeat();interval=window.setInterval(()=>void heartbeat(),5000)},0);const onVisibility=()=>{if(document.visibilityState==="visible")void heartbeat()};document.addEventListener("visibilitychange",onVisibility);return()=>{active=false;window.clearTimeout(starter);if(interval)window.clearInterval(interval);document.removeEventListener("visibilitychange",onVisibility)}},[ready,state.view,state.activeMapId,selectedId,serverVersion,dirty,syncConflict,refreshWorkspaceState]);
  useEffect(()=>()=>{void fetch("/api/realtime",{method:"DELETE",keepalive:true})},[]);

  const activeMap=state.maps.find(m=>m.id===state.activeMapId)!;
  const visibleNodes=useMemo(()=>state.nodes.filter(n=>n.mapId===state.activeMapId),[state.nodes,state.activeMapId]);
  const selected=state.nodes.find(n=>n.id===selectedId)||null;
  const reviewShareMap=reviewShareMapId?state.maps.find(map=>map.id===reviewShareMapId)||null:null;
  const selectedApprovals=selectedId?approvals.filter(approval=>approval.nodeId===selectedId):[];
  const pendingApprovals=approvals.filter(approval=>approval.mapId===state.activeMapId&&approval.status==="pending");
  const childrenByParent=useMemo(()=>{const m=new Map<string,NodeItem[]>();visibleNodes.forEach(n=>{if(n.parentId){const a=m.get(n.parentId)||[];a.push(n);m.set(n.parentId,a)}});return m},[visibleNodes]);
  const hiddenIds=useMemo(()=>{const hidden=new Set<string>();const walk=(id:string)=>{for(const c of childrenByParent.get(id)||[]){hidden.add(c.id);walk(c.id)}};visibleNodes.filter(n=>n.collapsed).forEach(n=>walk(n.id));return hidden},[visibleNodes,childrenByParent]);
  const mapDependencies=useMemo(()=>state.dependencies.filter(dependency=>visibleNodes.some(node=>node.id===dependency.nodeId)&&visibleNodes.some(node=>node.id===dependency.dependsOnId)),[state.dependencies,visibleNodes]);
  const operational=useMemo(()=>calculateOperationalState(visibleNodes,mapDependencies),[visibleNodes,mapDependencies]);
  const displayNodes=visibleNodes.filter(n=>!hiddenIds.has(n.id)).map(node=>operational.byId.get(node.id)??{...node,computedProgress:node.progress,computedStatus:node.status,computedBlockReason:node.blockedReason,isOverdue:false});
  const tourNodeId=displayNodes[0]?.id;
