  const loadReviewMarkers=useCallback(async(mapId:string)=>{
    try{const response=await fetch("/api/review-links?mapId="+encodeURIComponent(mapId),{cache:"no-store"});const data=await response.json();if(response.ok)setReviewMarkers(data.markers||[])}catch{}
  },[]);
  useEffect(()=>{const timer=window.setTimeout(()=>{if(!ready||state.view!=="map"||!state.activeMapId){setReviewMarkers([]);return}void loadReviewMarkers(state.activeMapId)},0);if(!ready||state.view!=="map"||!state.activeMapId)return()=>window.clearTimeout(timer);const interval=window.setInterval(()=>void loadReviewMarkers(state.activeMapId),15000);return()=>{window.clearTimeout(timer);window.clearInterval(interval)}},[ready,state.view,state.activeMapId,loadReviewMarkers]);
  const doneCount=operational.nodes.filter(n=>n.computedStatus==="done").length;
  const {blockedCount,projectProgress,health,nextAction,criticalCount}=operational;

